-- SEO: every SG AI course links back to the AI hub with the keyword "AI training in Singapore"
-- (user directive 2026-10-30: courses should also be found for "ai training" / "ai courses").
--
-- Adds one line after the intro paragraphs of each AI course overview (short_description) that is a
-- direct member of the AI Courses hub (/artificial-intelligence-courses.html, 226 courses):
--   <p>This course is part of our <a href="/artificial-intelligence-courses.html">AI training in Singapore</a>,
--   where you can browse all our AI courses. See more <a href="/<series>.html"><series keyword></a>.</p>
-- The series link is the course's most specific AI Series (Claude > Codex > Gemini > Copilot > AI security >
-- multi agents > AI agents > agentic > vibe coding > generative > applications > infrastructure).
-- Puts "AI training" + "AI courses" on every AI course page and gives the hub ~226 keyword-anchored internal
-- links. Inserted before the first heading/div/table, so view.phtml's section carving is unaffected.
--
-- Each UPDATE only INSERTs at a fixed character position and is guarded by MD5 of the text AFTER
-- migration 1879 (keyword bolding) - so it must run after 1879; a row edited since is skipped untouched.
-- SG-only (@sg guard). Idempotent. Post-deploy: catalog_product_flat reindex + cache flush.
-- MY / GH: the same line was applied DB-only on the partner servers 2026-10-30.

SET @sg := (SELECT COUNT(*) FROM core_store WHERE store_id = 1 AND code = 'singapore');
UPDATE catalog_product_entity_text SET value = CONCAT(value, '\n<p>This course is part of our <a href="/artificial-intelligence-courses.html">AI training in Singapore</a>, where you can browse all our AI courses. See more <a href="/generative-ai-series.html">generative AI training</a>.</p>') WHERE entity_id = 11 AND attribute_id = 73 AND store_id = 0 AND MD5(value) = '81154b4ea9bc841b479f3d11216740f7' AND @sg = 1;
